INSERT OR IGNORE INTO "blog_post" ("id", "title", "slug", "excerpt", "content", "image", "author", "tags", "is_published", "published_at", "created_at", "updated_at") VALUES ('blog-001', 'iPhone 16 Pro Max: Everything You Need to Know', 'iphone-16-pro-max-guide', 'A comprehensive look at Apple''s latest flagship smartphone featuring the A18 Pro chip and 48MP camera system.', 'Apple has once again raised the bar with the iPhone 16 Pro Max. Featuring the powerful A18 Pro chip, a stunning titanium design, and a 48MP camera system that rivals professional cameras.

The new 5x optical zoom lens is a game-changer for photography enthusiasts. Battery life has been improved to last up to 33 hours of video playback.

Available in four stunning finishes: Natural Titanium, Desert Titanium, White Titanium, and Black Titanium. Prices start at ৳159,900 for the 256GB model.', 'https://picsum.photos/seed/blog-iphone/1200/630', 'Tuktak Tech', 'iPhone,Apple,Smartphones,Review', 1, '2025-07-01T00:00:00.000Z', '2025-07-01T00:00:00.000Z', '2025-07-01T00:00:00.000Z');
INSERT OR IGNORE INTO "blog_post" ("id", "title", "slug", "excerpt", "content", "image", "author", "tags", "is_published", "published_at", "created_at", "updated_at") VALUES ('blog-002', 'Top 10 Gadgets Under ৳50,000 in Bangladesh', 'top-gadgets-under-50000', 'Our curated list of the best value-for-money electronics available in Bangladesh under ৳50,000.', 'Finding quality electronics on a budget in Bangladesh can be challenging. We''ve done the research so you don''t have to.

From noise-cancelling headphones to powerful smartphones, here are our top picks under ৳50,000:

1. Sony WH-1000XM6 - ৳35,000
2. Nothing Phone (3) - ৳54,999
3. Samsung Galaxy Watch 7 - ৳49,900
4. Xiaomi 14T Pro - ৳69,999

Each of these products offers exceptional value for their price point.', 'https://picsum.photos/seed/blog-gadgets/1200/630', 'Tuktak Team', 'Budget,Gadgets,Bangladesh,Guide', 1, '2025-07-01T00:00:00.000Z', '2025-07-01T00:00:00.000Z', '2025-07-01T00:00:00.000Z');
INSERT OR IGNORE INTO "blog_post" ("id", "title", "slug", "excerpt", "content", "image", "author", "tags", "is_published", "published_at", "created_at", "updated_at") VALUES ('blog-003', 'The Ultimate Guide to Wireless Headphones', 'wireless-headphones-guide-2025', 'Everything you need to know about choosing the perfect wireless headphones for your lifestyle.', 'Wireless headphones have become essential for modern life. Whether you''re working from home, commuting, or hitting the gym, the right pair can transform your experience.

Key factors to consider:

1. **Sound Quality**: Look for Hi-Res Audio support and LDAC codec
2. **Noise Cancellation**: Active Noise Cancellation (ANC) is essential for busy environments
3. **Battery Life**: Aim for 30+ hours for over-ear headphones
4. **Comfort**: Weight and ear cushion material matter for long sessions

Our top recommendation: Sony WH-1000XM6 offers the best balance of all these factors at ৳35,000.', 'https://picsum.photos/seed/blog-audio/1200/630', 'Audio Expert', 'Audio,Headphones,Guide,Wireless', 1, '2025-07-01T00:00:00.000Z', '2025-07-01T00:00:00.000Z', '2025-07-01T00:00:00.000Z');
INSERT OR IGNORE INTO "blog_post" ("id", "title", "slug", "excerpt", "content", "image", "author", "tags", "is_published", "published_at", "created_at", "updated_at") VALUES ('blog-004', 'MacBook Air M4 vs MacBook Pro M4: Which Should You Buy?', 'macbook-air-m4-vs-pro-m4', 'Comparing Apple''s latest laptops to help you decide which one is right for your needs and budget.', 'Apple''s M4 chip has brought incredible performance to both the MacBook Air and MacBook Pro. But which one should you choose?

**MacBook Air M4**
- Starting at ৳169,900
- 15.3-inch Liquid Retina display
- Fanless design, ultra-thin
- Perfect for students and general productivity

**MacBook Pro M4**
- Starting at ৳249,900
- 14.2-inch Liquid Retina XDR display
- Active cooling for sustained performance
- Ideal for professionals and creators

Verdict: The Air is perfect for most users. Choose the Pro only if you need sustained performance for video editing, coding, or 3D work.', 'https://picsum.photos/seed/blog-macbook/1200/630', 'Tech Reviewer', 'Apple,MacBook,Laptop,Comparison', 1, '2025-07-01T00:00:00.000Z', '2025-07-01T00:00:00.000Z', '2025-07-01T00:00:00.000Z');
